html:
{% if doc.doctype != 'Trip Invoice' %}
  {{ frappe.throw('Trip Invoice POS can only be printed from Trip Invoice.') }}
{% endif %}
{% if doc.status not in ['Ready', 'Sales Invoice Created'] or not doc.kashf_ready or not doc.grand_total %}
  {{ frappe.throw('Save Trip Invoice and mark it Ready before printing.') }}
{% endif %}
{%- set company_doc = frappe.get_doc('Company', doc.company) if doc.company and frappe.db.exists('Company', doc.company) else None -%}
{%- set company_name = (company_doc.company_name if company_doc else doc.company) or 'اسم المتجر' -%}
{%- set tax_id = (company_doc.tax_id if company_doc else '') or '' -%}
{%- set posting_date = doc.invoice_date or frappe.utils.nowdate() -%}
{%- set posting_time = frappe.utils.now_datetime().strftime('%H:%M:%S') -%}
{%- set from_parts = (doc.from_location or '').split('|') -%}
{%- set to_parts = (doc.to_location or '').split('|') -%}
{%- set from_label = (from_parts[1] if from_parts|length > 1 else from_parts[0] if from_parts|length else '').strip() -%}
{%- set to_label = (to_parts[1] if to_parts|length > 1 else to_parts[0] if to_parts|length else '').strip() -%}
{%- set route_description = (from_label ~ '-إلى-' ~ to_label) if from_label and to_label else '' -%}
<div class="pos-receipt">
  <div class="pos-title">فاتورة</div>
  <div class="pos-number">رقم الفاتورة <span class="ltr">{{ doc.name }}</span></div>

  <div class="pos-center">
    <div class="store-name">{{ company_name }}</div>
    <div class="store-sub">{{ doc.customer_name_text or doc.invoice_passenger_name or doc.customer or '' }}</div>
    {% if doc.invoice_passenger_mobile %}<div class="store-sub ltr">{{ doc.invoice_passenger_mobile }}</div>{% endif %}
  </div>

  <div class="meta">
    <div class="meta-row"><span><span class="label">الوقت:</span> <span class="value">{{ posting_time }}</span></span><span><span class="label">التاريخ:</span> <span class="value">{{ frappe.utils.formatdate(posting_date, 'dd/MM/yyyy') }}</span></span></div>
    {% if tax_id %}<div class="meta-row"><span class="label">الرقم الضريبي:</span><span class="value">{{ tax_id }}</span></div>{% endif %}
  </div>



  <div class="dash"></div>
  <table class="items">
    <thead>
      <tr>
        <th>المنتجات</th>
        <th class="num">الكمية</th>
        <th class="num">السعر</th>
        <th class="num">الإجمالي</th>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.items %}
      <tr>
        <td class="desc">{{ route_description or row.item_name or row.item_code or 'خدمة نقل' }}</td>
        <td class="num">{{ frappe.utils.fmt_money(row.qty, currency='') }}</td>
        <td class="num">{{ frappe.utils.fmt_money(row.rate, currency='') }}</td>
        <td class="num">{{ frappe.utils.fmt_money(row.total_amount, currency='') }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <table class="totals">
    <tr><td>الصافي</td><td class="amount">{{ frappe.utils.fmt_money(doc.net_total, currency='') }}</td></tr>
    <tr><td>ضريبة القيمة المضافة</td><td class="amount">{{ frappe.utils.fmt_money(doc.vat_amount, currency='') }}</td></tr>
    <tr class="grand"><td>المجموع (ريال)</td><td class="amount">{{ frappe.utils.fmt_money(doc.grand_total, currency='') }}</td></tr>
  </table>

  <div class="vat-note">يشمل ضريبة القيمة المضافة ({{ frappe.utils.fmt_money(doc.vat_rate or 15, currency='') }}%)</div>
  <div class="footer">شكراً لكم</div>
</div>
